/* prog27_soundex – reconstructed from the obfuscated binary
 *
 * The original binary implements the classic Soundex algorithm.
 * It prints "EMPTY" when no argument is supplied or when the
 * supplied string is empty.  Otherwise it prints a 4‑character
 * Soundex code: the first letter of the input (preserved case),
 * followed by three digits (or '0' padding) derived from the
 * remaining letters.
 *
 * The mapping used by the original `soundex_digit` function is:
 *
 *   B, F, P, V           -> 1
 *   C, G, J, K, Q, S, X, Z -> 2
 *   D, T                -> 3
 *   L                   -> 4
 *   M, N                -> 5
 *   R                   -> 6
 *   all other characters -> 0
 *
 * The implementation below reproduces exactly the observable
 * behaviour (stdout) of the original program.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for a given (uppercase) character. */
static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

/* Build the Soundex code for the supplied string. */
static void soundex(const char *s, char out[5])
{
    /* First character (preserve case as the original program does). */
    out[0] = s[0];
    int prev = soundex_digit(toupper(s[0]));
    int pos = 1;               /* position in out after the first letter */

    for (size_t i = 1; s[i] != '\0' && pos < 4; ++i) {
        int d = soundex_digit(toupper(s[i]));
        if (d == 0)               /* vowels and other ignored characters */
            continue;
        if (d == prev)            /* suppress duplicate digits */
            continue;
        out[pos++] = (char)('0' + d);
        prev = d;
    }

    /* Pad with '0' up to length 4. */
    while (pos < 4) {
        out[pos++] = '0';
    }
    out[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *input = argv[1];
    if (input[0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char code[5];
    soundex(input, code);
    puts(code);
    return 0;
}
